# Analyze the grid structure more carefully
grid = [
    [8, 6, 6, 8, 8, 8, 8, 6, 8, 8, 8, 8, 8],
    [8, 6, 8, 8, 8, 8, 6, 6, 8, 6, 8, 6, 8],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [8, 6, 8, 6, 8, 8, 8, 6, 8, 8, 8, 8, 6],
    [6, 6, 8, 8, 8, 8, 8, 6, 8, 8, 8, 8, 8],
    [8, 6, 8, 8, 6, 8, 8, 6, 8, 8, 8, 6, 8],
    [8, 6, 8, 6, 8, 8, 8, 6, 8, 8, 8, 8, 8],
    [8, 6, 8, 8, 8, 8, 8, 6, 8, 8, 8, 8, 6],
    [8, 6, 8, 8, 6, 6, 8, 6, 8, 8, 8, 8, 8],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [8, 6, 8, 8, 8, 8, 6, 6, 8, 8, 6, 8, 8],
    [8, 6, 8, 6, 8, 8, 8, 6, 8, 8, 8, 8, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [8, 6, 8, 8, 8, 6, 8, 6, 8, 8, 8, 8, 8]
]

# Find horizontal lines (full rows of 6s)
horizontal_lines = [i for i, row in enumerate(grid) if all(c == 6 for c in row)]
print(f"Horizontal separator rows: {horizontal_lines}")

# Find vertical separators
vertical_lines = [j for j in range(len(grid[0])) if all(grid[i][j] == 6 for i in range(len(grid)))]
print(f"Vertical separator columns: {vertical_lines}")

# Now let's identify the regions
# Regions are areas between separators (excluding the separator lines themselves)

regions = []
for r in range(len(grid)):
    if r in horizontal_lines:
        continue
    for c in range(len(grid[0])):
        if c in vertical_lines:
            continue
        regions.append((r, c))

print(f"\nNumber of region cells: {len(regions)}")
print(f"Regions at (row, col): {regions[:20]}...")

# Look at each region and see the pattern inside each
# Let's visualize by region
def get_region_id(r, c):
    if r < horizontal_lines[0]:
        if c < vertical_lines[0]:
            return 0  # top-left
        elif c < vertical_lines[1]:
            return 1  # top-middle
        else:
            return 2  # top-right
    elif r < horizontal_lines[1]:
        if c < vertical_lines[0]:
            return 3  # middle-left
        elif c < vertical_lines[1]:
            return 4  # middle-middle
        else:
            return 5  # middle-right
    elif r < horizontal_lines[2]:
        if c < vertical_lines[0]:
            return 6  # lower-left
        elif c < vertical_lines[1]:
            return 7  # lower-middle
        else:
            return 8  # lower-right
    elif r < horizontal_lines[3]:
        if c < vertical_lines[0]:
            return 9  # bottom-left
        elif c < vertical_lines[1]:
            return 10  # bottom-middle
        else:
            return 11  # bottom-right
    else:
        return 12  # very bottom

# Map each cell to its region
for r in range(len(grid)):
    if r in horizontal_lines:
        continue
    for c in range(len(grid[0])):
        if c in vertical_lines:
            continue
        reg_id = get_region_id(r, c)
        print(f"Cell ({r},{c}) -> region {reg_id}: value {grid[r][c]}")
        if c >= len(grid[0]) - 5:
            break
    if c >= len(grid[0]) - 5:
        break
